previewCss:
.darma-loader-wifi-pulse {
  position: relative;
  width: 54px;
  height: 34px;
}
.darma-loader-wifi-pulse::before {
  content: "";
  position: absolute;
  bottom: 2px;
  left: 50%;
  width: 8px;
  height: 8px;
  margin-left: -4px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-wifi-pulse-wblink 1.4s ease-in-out infinite;
}
.darma-loader-wifi-pulse i {
  position: absolute;
  bottom: 2px;
  left: 50%;
  border: 4px solid var(--loader-color, #6366f1);
  border-color: var(--loader-color, #6366f1) transparent transparent transparent;
  border-radius: 50%;
  box-sizing: border-box;
  transform: translateX(-50%);
  animation: darma-loader-wifi-pulse-wblink 1.4s ease-in-out infinite;
}
.darma-loader-wifi-pulse i:nth-child(1) { width: 22px; height: 22px; animation-delay: 0.15s; }
.darma-loader-wifi-pulse i:nth-child(2) { width: 38px; height: 38px; animation-delay: 0.3s; }
.darma-loader-wifi-pulse i:nth-child(3) { width: 54px; height: 54px; animation-delay: 0.45s; }
@keyframes darma-loader-wifi-pulse-wblink {
  0%, 65%, 100% { opacity: 0.2; }
  30% { opacity: 1; }
}

